#[cfg(test)]
use std::fs;
#[cfg(test)]
use std::path::PathBuf;
#[cfg(test)]
use std::sync::atomic::{AtomicU64, Ordering};

/// The first line of every file this command generates.
///
/// A target file is replaced only when its first line is this marker, so an
/// unrelated file whose name collides with a page is a refusal, never a
/// replacement. The marker is static text: no build date, no host path.
pub(crate) const GENERATED_MARKER: &str =
    "<!-- generated by `clio help --markdown`; edits to this file are replaced -->";

/// One manual file: its page name inside `--out` and its bytes.
struct Page {
    file: String,
    bytes: String,
}

/// The whole manual: the per-leaf pages in write order, then the index.
struct Manual {
    pages: Vec<Page>,
    index: Page,
}

impl Manual {
    /// Every file in write order: the pages sorted by page name, then the
    /// index, so a run that stops early leaves no index promising pages it
    /// never wrote.
    fn write_order(&self) -> impl Iterator<Item = &Page> {
        self.pages.iter().chain(std::iter::once(&self.index))
    }
}

/// Render the whole manual without touching the disk: one page per registered
/// leaf command, plus the index.
fn render_manual() -> Manual {
    let specs: Vec<&CommandSpec> = cli_command_registry::all().collect();
    let page_map = PageMap::new(specs.iter().map(|spec| spec.name));
    let mut entries: Vec<(&CommandSpec, String)> = specs
        .iter()
        .map(|spec| {
            let file = page_map
                .page(spec.name)
                .expect("every registered name has a page")
                .to_owned();
            (*spec, file)
        })
        .collect();
    entries.sort_unstable_by(|a, b| a.0.name.cmp(b.0.name));
    let index_entries: Vec<(&str, String)> = entries
        .iter()
        .map(|(spec, file)| (spec.name, file.clone()))
        .collect();
    let mut pages: Vec<Page> = entries
        .iter()
        .map(|(spec, file)| Page {
            file: file.clone(),
            bytes: marked(&render_command_page(spec, &page_map)),
        })
        .collect();
    pages.sort_unstable_by(|a, b| a.file.cmp(&b.file));
    Manual {
        pages,
        index: Page {
            file: PageMap::index_page().to_owned(),
            bytes: marked(&index_text(&index_entries)),
        },
    }
}

/// The index page: its title, then one sorted link per leaf page.
fn index_text(entries: &[(&str, String)]) -> String {
    let mut text = String::from("# clio help index\n\n");
    for (name, file) in entries {
        text.push_str("- [");
        text.push_str(name);
        text.push_str("](");
        text.push_str(file);
        text.push_str(")\n");
    }
    text
}

/// `page` with the generated-by marker as its first line.
fn marked(page: &str) -> String {
    format!("{GENERATED_MARKER}\n{page}")
}

/// Write the manual into `out_dir`, replacing only files this command
/// generated.
///
/// `--out` is resolved exactly once, into a held directory: the walk that
/// inspects each component is the walk that creates a missing one and the walk
/// whose result every later operation names. Every target is then checked
/// against that held directory, and each file is written through a same-directory
/// temp sibling created, given its mode, synced, and promoted inside it. Because
/// no step resolves the path a second time, a component or a page target
/// swapped for a symlink after its check cannot redirect a generated page: the
/// check and the write share one directory inode, and the temp create refuses an
/// existing name rather than following it. The page map has already
/// collision-checked the page names, so the index and the pages never share a
/// name. A failure after the first promotion leaves the files already written in
/// place and reports the step that failed, because std has no multi-file atomic
/// swap.
///
/// # Errors
/// A directory, target, or write failure, as a `usage` error for a refused
/// path and an operational error for a write step.
pub(crate) fn write_manual(out_dir: &Path) -> Result<(), CliError> {
    let manual = render_manual();
    let dir = OutDir::open(out_dir)?;
    for page in manual.write_order() {
        dir.check_target(&page.file)?;
    }
    for page in manual.write_order() {
        write_page(&dir, out_dir, page)?;
    }
    Ok(())
}

/// Write one page through a same-directory temp sibling in the held directory:
/// create-new, write, restore the mode, sync, then promote with a rename of two
/// bare names in that directory. A temp that cannot be created reports the plain
/// write error and leaves the directory as it was; a failure after the temp
/// exists removes the temp and reports the manual incomplete.
fn write_page(dir: &OutDir, out_dir: &Path, page: &Page) -> Result<(), CliError> {
    let tmp = dir.write_temp(&page.file, page.bytes.as_bytes())?;
    if let Err(err) = dir.promote(&tmp, &page.file) {
        dir.remove_temp(&tmp);
        return Err(incomplete(out_dir, &err));
    }
    Ok(())
}

/// The failure a write step reports: which step failed, and that the manual in
/// the directory is now incomplete.
pub(crate) fn incomplete(out_dir: &Path, error: &CliError) -> CliError {
    CliError::operational(
        "manual_incomplete",
        format!(
            "{} The manual in `{}` is incomplete.",
            error.message(),
            out_dir.display()
        ),
    )
}

